from __future__ import annotations

import socket
from dataclasses import dataclass, field
from datetime import datetime
from enum import Enum
from typing import Optional


class Severity(str, Enum):
    LOW = "low"
    MEDIUM = "medium"
    HIGH = "high"
    CRITICAL = "critical"

    def rank(self) -> int:
        return {self.LOW: 1, self.MEDIUM: 2, self.HIGH: 3, self.CRITICAL: 4}[self]


class Confidence(str, Enum):
    LOW = "low"
    MEDIUM = "medium"
    HIGH = "high"

    def rank(self) -> int:
        return {self.LOW: 1, self.MEDIUM: 2, self.HIGH: 3}[self]


class Module(str, Enum):
    FILESYSTEM = "filesystem"
    SHELL_HISTORY = "shell-history"
    KEYCHAIN = "keychain"
    PROCESS_ENV = "process-env"
    INSTALLED_TOOLS = "installed-tools"
    NETWORK = "network"
    DOCKER = "docker"
    CHROME = "chrome"
    LAN = "lan"
    INTERNET = "internet"


DEFAULT_MODULES = [
    Module.FILESYSTEM,
    Module.SHELL_HISTORY,
    Module.KEYCHAIN,
    Module.PROCESS_ENV,
    Module.INSTALLED_TOOLS,
    Module.NETWORK,
    Module.DOCKER,
    Module.CHROME,
]

OPT_IN_MODULES = [Module.LAN, Module.INTERNET]


@dataclass
class Finding:
    fingerprint: str = ""
    rule_id: str = ""
    description: str = ""
    severity: Severity = Severity.LOW
    confidence: Confidence = Confidence.HIGH
    module: Module = Module.FILESYSTEM
    file_path: str = ""
    location: str = ""
    redacted_value: str = ""
    redacted_context: str = ""
    secret_hash: str = ""
    tags: list[str] = field(default_factory=list)
    detected_at: datetime = field(default_factory=lambda: datetime.utcnow())
    file_identity: bool = False
    placeholder: bool = False
    additional_files: list[str] = field(default_factory=list)
    also_matched: list[str] = field(default_factory=list)
    # keychain-specific
    service: str = ""
    account: str = ""
    # process-specific
    pid: str = ""
    process_name: str = ""

    def to_dict(self) -> dict:
        d = {
            "fingerprint": self.fingerprint,
            "rule_id": self.rule_id,
            "description": self.description,
            "severity": self.severity.value,
            "confidence": self.confidence.value,
            "module": self.module.value,
            "file_path": self.file_path,
            "location": self.location,
            "redacted_value": self.redacted_value,
            "redacted_context": self.redacted_context,
            "secret_hash": self.secret_hash,
            "tags": self.tags,
            "detected_at": self.detected_at.isoformat() + "Z",
            "file_identity": self.file_identity,
            "placeholder": self.placeholder,
        }
        if self.additional_files:
            d["additional_files"] = self.additional_files
        if self.also_matched:
            d["also_matched"] = self.also_matched
        if self.service:
            d["service"] = self.service
        if self.account:
            d["account"] = self.account
        if self.pid:
            d["pid"] = self.pid
        if self.process_name:
            d["process_name"] = self.process_name
        return d


@dataclass
class ModuleStatus:
    module: Module = Module.FILESYSTEM
    attempted: int = 0
    accessed: int = 0
    skipped: int = 0
    note: str = ""

    def to_dict(self) -> dict:
        return {
            "module": self.module.value,
            "attempted": self.attempted,
            "accessed": self.accessed,
            "skipped": self.skipped,
            "note": self.note,
        }


