@dataclass
class InternetCheck:
    name: str = ""
    host: str = ""
    port: int = 0
    protocol: str = ""
    reachable: bool = False
    error: str = ""

    def to_dict(self) -> dict:
        d = {
            "name": self.name,
            "host": self.host,
            "port": self.port,
            "protocol": self.protocol,
            "reachable": self.reachable,
        }
        if self.error:
            d["error"] = self.error
        return d


@dataclass
class InternetStatus:
    public_ip: str = ""
    checks: list[InternetCheck] = field(default_factory=list)

    def to_dict(self) -> dict:
        return {
            "public_ip": self.public_ip,
            "checks": [c.to_dict() for c in self.checks],
        }


