@dataclass
class ChromeCookie:
    domain: str = ""
    name: str = ""
    value: str = ""
    path: str = ""
    expires: float = 0.0
    size: int = 0
    http_only: bool = False
    secure: bool = False
    session: bool = False
    same_site: str = ""

    def to_dict(self) -> dict:
        d: dict = {
            "domain": self.domain, "name": self.name, "path": self.path,
            "secure": self.secure, "http_only": self.http_only,
            "session": self.session, "size": self.size,
        }
        if self.same_site:
            d["same_site"] = self.same_site
        if self.expires:
            d["expires"] = self.expires
        return d


@dataclass
class ChromeProfile:
    dir_name: str = ""
    display_name: str = ""
    gaia_name: str = ""
    url: str = ""
    launched: bool = False
    cookies: list[ChromeCookie] = field(default_factory=list)
    screenshot_png: bytes = field(default_factory=bytes, repr=False)
    screenshot_bytes: int = 0
    error: str = ""

    def to_dict(self) -> dict:
        d: dict = {
            "dir_name": self.dir_name,
            "display_name": self.display_name,
            "url": self.url,
            "launched": self.launched,
            "cookies_by_domain": {},
        }
        by_domain: dict[str, int] = {}
        for c in self.cookies:
            by_domain[c.domain] = by_domain.get(c.domain, 0) + 1
        d["cookies_by_domain"] = dict(sorted(by_domain.items(), key=lambda x: -x[1])[:30])
        if self.screenshot_bytes:
            d["screenshot_bytes"] = self.screenshot_bytes
        if self.error:
            d["error"] = self.error
        return d


@dataclass
class ChromeStatus:
    installed: bool = False
    binary_path: str = ""
    version: str = ""
    user_data_dir: str = ""
    profiles: list[ChromeProfile] = field(default_factory=list)
    copy_bytes: int = 0
    error: str = ""

    def to_dict(self) -> dict:
        d: dict = {
            "installed": self.installed,
            "binary_path": self.binary_path,
            "version": self.version,
            "user_data_dir": self.user_data_dir,
            "profiles": [p.to_dict() for p in self.profiles],
        }
        if self.copy_bytes:
            d["copy_bytes"] = self.copy_bytes
        if self.error:
            d["error"] = self.error
        return d


@dataclass
class RunMeta:
    started_at: datetime = field(default_factory=lambda: datetime.utcnow())
    finished_at: Optional[datetime] = None
    hostname: str = field(default_factory=lambda: socket.gethostname())
    paths: list[str] = field(default_factory=list)
    modules: list[Module] = field(default_factory=list)
    module_statuses: list[ModuleStatus] = field(default_factory=list)
    severity_counts: dict[str, int] = field(default_factory=dict)
    suppressed: int = 0
    allowlisted: int = 0
    tools: list[Tool] = field(default_factory=list)
    listeners: list[Listener] = field(default_factory=list)
    lan_devices: list[LANDevice] = field(default_factory=list)
    interfaces: list[NetworkInterface] = field(default_factory=list)
    internet: Optional[InternetStatus] = None
    docker: Optional[DockerStatus] = None
    chrome: Optional[ChromeStatus] = None

    def to_dict(self) -> dict:
        d: dict = {
            "started_at": self.started_at.isoformat() + "Z",
            "finished_at": self.finished_at.isoformat() + "Z" if self.finished_at else None,
            "hostname": self.hostname,
            "paths": self.paths,
            "modules": [m.value for m in self.modules],
            "module_statuses": [s.to_dict() for s in self.module_statuses],
            "severity_counts": self.severity_counts,
            "suppressed": self.suppressed,
            "allowlisted": self.allowlisted,
        }
        if self.tools:
            d["tools"] = [t.to_dict() for t in self.tools]
        if self.listeners:
            d["listeners"] = [l.to_dict() for l in self.listeners]
        if self.lan_devices:
            d["lan_devices"] = [dev.to_dict() for dev in self.lan_devices]
        if self.interfaces:
            d["interfaces"] = [i.to_dict() for i in self.interfaces]
        if self.internet:
            d["internet"] = self.internet.to_dict()
        if self.docker:
            d["docker"] = self.docker.to_dict()
        if self.chrome:
            d["chrome"] = self.chrome.to_dict()
        return d


@dataclass
class RunResult:
    findings: list[Finding] = field(default_factory=list)
    suppressed: list[Finding] = field(default_factory=list)
    meta: RunMeta = field(default_factory=RunMeta)
